// Alegra devuelve máximo 30 facturas de proveedor por llamada, así que el nodo
// anterior hace varias llamadas y entrega una página por cada una.
// Aquí las abrimos para quedar con una factura por item.

const facturas = [];

for (const item of items) {
  const cuerpo = item.json;
  if (Array.isArray(cuerpo)) {
    facturas.push(...cuerpo);
  } else if (Array.isArray(cuerpo.data)) {
    facturas.push(...cuerpo.data);
  } else {
    facturas.push(cuerpo);
  }
}

return facturas.map((factura) => ({ json: factura }));

// ─── Puedes cambiar esto ──────────────────────────────────────────────
const DIAS_HACIA_ADELANTE = 15;  // hasta cuántos días adelante mirar
const MONEDA = 'COP';            // solo afecta cómo se ve la plata
const INCLUIR_VENCIDAS = true;   // false si solo quieres lo que está por vencer
// ──────────────────────────────────────────────────────────────────────

// La fecha de hoy, a la medianoche, en la zona horaria de tu n8n.
const hoy = new Date();
hoy.setHours(0, 0, 0, 0);

const plata = (n) =>
  new Intl.NumberFormat('es-CO', {
    style: 'currency',
    currency: MONEDA,
    maximumFractionDigits: 0,
  }).format(n);

// Una fecha sin hora la lee JavaScript como UTC y en Colombia queda corrida
// un día. Por eso le pegamos la medianoche local.
const fecha = (d) => {
  if (!d) return null;
  const f = new Date(String(d).slice(0, 10) + 'T00:00:00');
  return isNaN(f.getTime()) ? null : f;
};

const aTexto = (f) => {
  const p = (n) => String(n).padStart(2, '0');
  return f.getFullYear() + '-' + p(f.getMonth() + 1) + '-' + p(f.getDate());
};

// El nombre del proveedor llega distinto según el país. Lo normalizamos.
const nombreDe = (p) => {
  const n = p && p.name;
  if (Array.isArray(n)) return n.filter(Boolean).join(' ');
  if (n && typeof n === 'object') return [n.firstName, n.lastName].filter(Boolean).join(' ');
  return n || 'Proveedor sin nombre';
};

const numeroDe = (f) =>
  String(
    (f.numberTemplate && f.numberTemplate.fullNumber) ||
      f.billNumber ||
      f.number ||
      f.id
  );

const filas = [];

for (const item of items) {
  const f = item.json;

  // Lo que falta por pagar viene en 'balance'. Si esa cuenta no lo trae,
  // lo deducimos del total menos lo ya pagado.
  const falta = Number(f.balance ?? Number(f.total ?? 0) - Number(f.totalPaid ?? 0));
  if (!(falta > 0)) continue;

  const vence = fecha(f.dueDate) || fecha(f.date);
  if (!vence) continue;

  // Positivo: le quedan días. Negativo: ya se venció.
  const dias = Math.round((vence - hoy) / 86400000);

  if (dias > DIAS_HACIA_ADELANTE) continue;
  if (dias < 0 && !INCLUIR_VENCIDAS) continue;

  let estado;
  if (dias < 0) estado = 'Vencida';
  else if (dias === 0) estado = 'Vence hoy';
  else if (dias <= 3) estado = 'Esta semana';
  else estado = 'Por vencer';

  // Semana calendario a la que cae el vencimiento, contada desde hoy.
  const semana = dias < 0 ? 'Vencidas' : dias <= 6 ? 'Esta semana' : 'Próxima semana';

  filas.push({
    idAlegra: String(f.id),
    numero: numeroDe(f),
    proveedor: nombreDe(f.provider || f.client),
    vence: aTexto(vence),
    dias,
    diasTexto: dias < 0 ? Math.abs(dias) + ' días vencida' : dias === 0 ? 'hoy' : 'en ' + dias + ' días',
    estado,
    semana,
    total: Math.round(Number(f.total ?? 0)),
    pagado: Math.round(Number(f.totalPaid ?? 0)),
    falta: Math.round(falta),
    faltaTexto: plata(falta),
    moneda: (f.currency && f.currency.code) || MONEDA,
    actualizado: aTexto(hoy),
  });
}

// Primero lo más urgente.
filas.sort((a, b) => a.dias - b.dias || b.falta - a.falta);

return filas.map((fila) => ({ json: fila }));

// ─── Puedes cambiar esto ──────────────────────────────────────────────
const MONEDA = 'COP';
// ──────────────────────────────────────────────────────────────────────

const filas = items.map((i) => i.json);

const plata = (n) =>
  new Intl.NumberFormat('es-CO', {
    style: 'currency',
    currency: MONEDA,
    maximumFractionDigits: 0,
  }).format(n);

const escapar = (t) =>
  String(t ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

const total = filas.reduce((s, f) => s + f.falta, 0);
const vencidas = filas.filter((f) => f.dias < 0);
const estaSemana = filas.filter((f) => f.dias >= 0 && f.dias <= 6);
const proxima = filas.filter((f) => f.dias > 6);

const sumar = (lista) => lista.reduce((s, f) => s + f.falta, 0);

const bloque = (titulo, lista, color) => {
  if (!lista.length) return '';
  const cuerpo = lista
    .map(
      (f) =>
        '<tr>' +
        '<td style="padding:8px 12px;border-bottom:1px solid #eee;">' + escapar(f.proveedor) + '</td>' +
        '<td style="padding:8px 12px;border-bottom:1px solid #eee;">' + escapar(f.numero) + '</td>' +
        '<td style="padding:8px 12px;border-bottom:1px solid #eee;">' + escapar(f.vence) + '</td>' +
        '<td style="padding:8px 12px;border-bottom:1px solid #eee;">' + escapar(f.diasTexto) + '</td>' +
        '<td style="padding:8px 12px;border-bottom:1px solid #eee;text-align:right;"><strong>' + escapar(f.faltaTexto) + '</strong></td>' +
        '</tr>'
    )
    .join('');

  return (
    '<h3 style="color:' + color + ';margin:24px 0 8px;">' + titulo +
    ' — ' + plata(sumar(lista)) + ' <span style="font-weight:normal;color:#666;">(' + lista.length + ')</span></h3>' +
    '<table style="border-collapse:collapse;width:100%;font-size:14px;">' +
    '<tr style="text-align:left;background:#f6f6f6;">' +
    '<th style="padding:8px 12px;">Proveedor</th>' +
    '<th style="padding:8px 12px;">Factura</th>' +
    '<th style="padding:8px 12px;">Vence</th>' +
    '<th style="padding:8px 12px;">Cuándo</th>' +
    '<th style="padding:8px 12px;text-align:right;">Falta pagar</th>' +
    '</tr>' + cuerpo + '</table>'
  );
};

const asunto =
  'Pagos de la quincena: ' + plata(total) + ' en ' + filas.length +
  (filas.length === 1 ? ' factura' : ' facturas');

const mensaje =
  '<div style="font-family:Inter,Arial,sans-serif;color:#333;max-width:720px;">' +
  '<h2 style="color:#30bbb7;margin:0 0 4px;">Esto es lo que tienes que pagar</h2>' +
  '<p style="margin:0 0 16px;color:#666;">' +
  'En total <strong>' + plata(total) + '</strong> repartidos en ' + filas.length +
  (filas.length === 1 ? ' factura' : ' facturas') + '.</p>' +
  bloque('Ya vencidas', vencidas, '#c0392b') +
  bloque('Esta semana', estaSemana, '#d68910') +
  bloque('Próxima semana', proxima, '#30bbb7') +
  '<p style="margin-top:24px;color:#888;font-size:12px;">' +
  'Sale de tus facturas de proveedor abiertas en Alegra. El detalle completo quedó en tu hoja de Google.' +
  '</p></div>';

return [{ json: { asunto, mensaje, total, cantidad: filas.length } }];
